update public.fields set verification_status='verified_against_standard', verification_quote='Während die Projektleitung als Linienfunktion im Organigramm des Projekts eingebunden ist, bildet die Projektsteuerung als „Stabsstelle“ zur Projektleitung im Wesentlichen die Handlungsbereiche Projektorganisation, das Terminmanagement, das Kostenmanagement, das Qualitätsmanagement und das Vertragsmanagement ab. — printed p.19', verification_note='md-verified 2026-09-05 (§4.1 p.19) [VC] — the printed list has five Handlungsbereiche; "Risikomanagement" (§4.8 p.35) is EKOWAI''s sixth option', verified_at=now() where id='24b40624-1a68-4a5b-aa13-21e33a6d3e14' and verification_status not in ('verified_against_standard','corrected');

-- mgmt_cycle_frequency
update public.fields set verification_status='verified_against_standard', verification_quote='Der Management-Regelkreis ist auf die organisatorischen Aspekte des Projekts gerichtet und differenziert den Begriff „Management“ in vier Tätigkeiten, die kontinuierlich in meist zwei- bis vierwöchigen Abständen durchlaufen werden (siehe Bild 2). — printed p.20', verification_note='md-verified 2026-09-05 (§4.2 p.20) [VC] — printed range "meist zwei- bis vierwöchig" (standard_range, SR-2: selection is the engineer''s); the 2/3/4-week enum steps are EKOWAI''s discretisation', verified_at=now() where id='ad6553cf-8069-430b-8772-e3e06489fa01' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-06 Statusberichte und Änderungsmanagement ----------

-- mgmt_cycle_kontrollieren
update public.fields set verification_status='verified_against_standard', verification_quote='Der Fortschritt wird überprüft. Grundlage dafür ist ein detaillierter Plan in der Phase „Planen“. [...] Der Soll-Ist-Vergleich stellt die Planung und das Kontrollergebnis gegenüber, die Abweichungsanalyse fokussiert die Abweichungen und stellt den Einfluss auf die Zieländerungen dar. — printed p.21', verification_note='md-verified 2026-09-05 (§4.2 Kontrollieren, p.21) [VC]', verified_at=now() where id='8ccdf89a-47d4-46e6-9100-256dfa85e46b' and verification_status not in ('verified_against_standard','corrected');

-- mgmt_cycle_steuern
update public.fields set verification_status='verified_against_standard', verification_quote='Anhand der Abweichungsanalyse werden Überlegungen angestellt, mit welchen Maßnahmen im Projekt die weiteren Planungen im Projekt so verändert werden können, dass die Projektziele wieder eingehalten werden können. — printed p.21', verification_note='md-verified 2026-09-05 (§4.2 Steuern, p.21; cadence "meist zwei- bis vierwöchig" §4.2 p.20) [VC]', verified_at=now() where id='57dd550a-b143-4ec4-bce6-ff15429ef4ec' and verification_status not in ('verified_against_standard','corrected');

-- change_log_present
update public.fields set verification_status='verified_against_standard', verification_quote='Im Projekthandbuch sind der Prozess für das Änderungsmanagement sowie die anzuwendenden Formulare bereitgestellt. | Besprechungen werden mindestens mit Tagesordnung, Liste offener Punkte (LOP) und Zeitplanung vorbereitet. — printed p.26, p.40', verification_note='md-verified 2026-09-05 (§4.3.7 p.26; LOP §5.3.1 p.40; abbreviation LOP §2.2 p.14) [VC]', verified_at=now() where id='704c3a17-076d-44dd-987b-634ad76d3bd9' and verification_status not in ('verified_against_standard','corrected');

-- change_impact_documented
update public.fields set verification_status='verified_against_standard', verification_quote='Vor einer endgültigen Festlegung ist insbesondere zu klären, welche Auswirkungen auf die Projektziele bestehen, d. h. die Auswirkungen auf die Termine, die Kosten und die Qualitäten sind zu eruieren und als Grundlage für eine Entscheidung dem Auftraggeber vorzulegen. | Der Auslöser bzw. Verursacher für die Projektänderung und die Kostenübernahmen werden geklärt und müssen in Textform dokumentiert werden. Auswirkungen auf die Projektziele (Termine, Kosten, Qualitäten, inklusive Planungskosten) sind geklärt und beschrieben. — printed p.12, p.26', verification_note='md-verified 2026-09-05 (§2.1 Änderungsmanagement p.12; §4.3.7 p.26) [VC] — clause_reference §2.1 → §2.1, §4.3.7 proposed in STAGED S-3', verified_at=now() where id='e9c6d385-1033-44c4-92b1-3af93d142284' and verification_status not in ('verified_against_standard','corrected');

-- status_report_frequency
update public.fields set verification_status='verified_against_standard', verification_quote='Die Frequenz von Statusberichten orientiert sich am Projekt- oder Baufortschritt. In der Regel werden mindestens vierteljährliche Statusberichte konsequent geführt. | Der Berichtsturnus sollte sich am Projekt- oder Baufortschritt orientieren. Es bietet sich in der Regel ein vierteljährlicher Turnus an. — printed p.25', verification_note='md-verified 2026-09-05 (§4.3.6 p.25; §4.3.1 p.21 "In der Regel vierteljährliche Projekt- oder Statusberichte") [VC] — the source prints only the floor "mindestens vierteljährlich"; weekly/biweekly/monthly/ad_hoc are EKOWAI''s options. Anhang A (p.84) carries NO cadence, only "Periode: von … bis" — clause_reference retag in STAGED S-3', verified_at=now() where id='25e15984-c9c2-4129-a1a1-811140919b97' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-07 Terminmanagement ----------

-- master_schedule_present
update public.fields set verification_status='verified_against_standard', verification_quote='Die Terminplanung ist in verschiedene Planungsebenen strukturiert. Die Terminpläne für die Entscheidungsebenen werden als Rahmenterminpläne bezeichnet. Sie enthalten hauptsächlich die wesentlichen Meilensteine und sind übersichtlich in der Darstellung. Der Generalablaufplan stellt über das ganze Projekt eine durchgängige Terminplanung dar, die so detailliert ist, dass die wesentlichen Vertragstermine für die Planung und Ausführung daraus entnommen werden können. — printed p.26', verification_note='md-verified 2026-09-05 (§4.4.1 p.26; §5.5.4 p.50) [VC]', verified_at=now() where id='ffb502a0-af64-445d-ab8f-c4f438202098' and verification_status not in ('verified_against_standard','corrected');

-- detailed_schedule_present
update public.fields set verification_status='verified_against_standard', verification_quote='Phasenbezogen werden Steuerungsterminpläne erstellt, die so detailliert sind, dass die Abhängigkeiten der Leistungen der einzelnen Beteiligten eingearbeitet sind und so eine Kontrolle und Steuerung des Termingeschehens in Planung, Ausschreibung, Ausführung und Inbetriebnahme ermöglichen. Detailterminpläne oder detaillierte Bauzeitenpläne sind die finale Detaillierungsstufe der Auftragnehmer und der ausführenden Firmen, zur Planung und Koordinierung der eigenen Leistungen. | Der Auftraggeber hat die „Terminhoheit“ in seinem Projekt. Er plant die von ihm beizusteuernden Aktivitäten in Verbindung mit den Terminplänen, die von Projektbeteiligten beizusteuern sind. — printed p.26, p.27', verification_note='md-verified 2026-09-05 (§4.4.1 p.26; §4.4.2 p.27) [VC] — caveat: the description labels the Termindetailplan as the Auftraggeber''s, but §4.4.1 makes Detailterminpläne the Auftragnehmer/ausführende-Firmen level; the AG''s levels are Rahmen-/Generalablauf-/Steuerungsterminplan (STAGED S-3 note)', verified_at=now() where id='e3425b9c-6779-4e87-b5ae-132e25c4ad87' and verification_status not in ('verified_against_standard','corrected');

-- contractor_schedule_resources
update public.fields set verification_status='verified_against_standard', verification_quote='Der Auftragnehmer nimmt die Leistung „Terminplanung“ ernst und erkennt die Notwendigkeit, diese umfassend und vernünftig im Rahmen des beauftragten Umfangs zu erbringen. | Aufbau von Ressourcen, die sich mit den Projektarten und den Methoden der Terminplanung (Netzplantechnik) auskennen. Gegebenenfalls kann dies auch von Dienstleistungsunternehmen erbracht werden; Grund-Know-how muss beim Auftragnehmer mindestens vorhanden sein. — printed p.28', verification_note='md-verified 2026-09-05 (§4.4.3 p.28) [VC]', verified_at=now() where id='ad582351-d530-4fde-9437-a3408f3c5e88' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-08 Kostenmanagement ----------

-- cost_planning_din276
update public.fields set verification_status='verified_against_standard', verification_quote='Die Kostenplanung erfolgt mit den gängigen Verfahren der Kostenplanung und geeignet ausgewählten Kostenkennwerten. [...] Eine einheitliche und durchgängige Kostenstruktur ist im Projekt vereinbart (bspw. DIN 276). Ausreichende Puffer (Reserven) sind eingeplant. | Alle Kostenelemente (beispielsweise alle Kostengruppen der DIN 276) sowie Risiken, Reserven und Preisentwicklungen sind berücksichtigt und transparent an die Auftragnehmer kommuniziert. — printed p.29, p.30', verification_note='md-verified 2026-09-05 (§4.5.1 p.29; §4.5.2 p.30) [VC] — caveat: the binding rule is a uniform cost structure; DIN 276 is printed as "bspw."/"beispielsweise" only. Label/gate REQ-12 over-specify DIN 276 (STAGED S-4/S-6)', verified_at=now() where id='16a4a27c-37f1-4878-b316-def6145d5d0d' and verification_status not in ('verified_against_standard','corrected');

-- life_cycle_cost_considered
update public.fields set verification_status='verified_against_standard', verification_quote='Die Lebenszykluskosten (LZK) umfassen alle Kosten der Entwicklung, der Planung, der Errichtung, des Betriebs, der Reinvestition, der Stilllegung sowie des Rückbaus eines Bauwerks oder einer Anlage. Dabei sind auch die Erlöse zu betrachten, z. B. aus der Gasverwertung oder dem Recycling. | Grundgedanken einer umfassenden Qualitätsbetrachtung können unter anderem der Lebenszykluskostenansatz, der ein gemeinsames Optimum zwischen Investitions- und Betriebskosten sucht, Nachhaltigkeits- und energetische Optimierungen sowie die Berücksichtigung von Umweltaspekten sein. — printed p.13, p.15', verification_note='md-verified 2026-09-05 (§2.1 Lebenszykluskosten p.13, definition sourced from DWA-M 820-1:2020; §3 p.15) [VC]', verified_at=now() where id='fd2cb127-e448-4c08-bb22-ff9eb1cb95d2' and verification_status not in ('verified_against_standard','corrected');

-- cost_control_documented
update public.fields set verification_status='verified_against_standard', verification_quote='Die Kostenkontrolle stellt in regelmäßigen Zeitabständen den Kostenstand beispielweise der aktuell vorgelegten Planungen fest und vergleicht diese mit den Festlegungen aus dem Kostenplan. Abweichungen vom Soll werden über einen Soll-Ist-Vergleich identifiziert. | Die eingesetzten Werkzeuge des Kostenmanagements müssen eine transparente und dauerhafte Dokumentation von Entwicklungen der Kostensituation ermöglichen. — printed p.30, p.31', verification_note='md-verified 2026-09-05 (§4.5.1 p.30; §4.5.4 p.31; §5.6.1 p.50) [VC]', verified_at=now() where id='edc3095d-043a-4cec-acfe-c4ff618325a0' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-09 Vertrags- und Qualitätsmanagement ----------

-- contract_amendments_tracked
update public.fields set verification_status='verified_against_standard', verification_quote='Vertragsänderungen sind in einem gesonderten Dokument festzuhalten, nicht nur in Protokollen der Planungs- bzw. Baubesprechungen. Der Bezug zum Ursprungsvertrag ist herzustellen. — printed p.33', verification_note='md-verified 2026-09-05 (§4.6.1 p.33) [VC]', verified_at=now() where id='fb45c63c-7347-4cf6-95d7-adfbef61bc09' and verification_status not in ('verified_against_standard','corrected');

-- approval_procedure_defined
update public.fields set verification_status='verified_against_standard', verification_quote='Nach jeder abgeschlossenen Leistungsphase erfolgt eine Freigabe der Planungsleistungen. Passend zum Projektablauf und zur Projektlaufzeit wird auch die Abnahme der Planungsleistungen geregelt. Im Vertrag wird festgelegt, dass Teilabnahmen (beispielsweise von Bauabschnitten oder Funktionseinheiten) möglich sind. | Formalisierte Dokumente für die Freigabe und für die Abnahme von Planungsleistungen werden vorbereitet und genutzt. — printed p.33', verification_note='md-verified 2026-09-05 (§4.6.2 p.33) [VC]', verified_at=now() where id='a0bf14df-a867-427f-b440-3ac49b4bc6da' and verification_status not in ('verified_against_standard','corrected');

-- quality_monitoring_active
update public.fields set verification_status='verified_against_standard', verification_quote='Eine phasenbezogene Prüfung der Qualität der Ingenieurleistungen wird in einem Qualitätssicherungsplan festgelegt, der neben der Eigenüberwachung auch die Fremdüberwachung festlegt. — printed p.34', verification_note='md-verified 2026-09-05 (§4.7.1 p.34) [VC]', verified_at=now() where id='4c7fb590-dcfd-4267-9d61-1e20f3c670bb' and verification_status not in ('verified_against_standard','corrected');

-- qs_plan_lph8_present
update public.fields set verification_status='verified_against_standard', verification_quote='Ein fundierter Qualitätssicherungsplan mit entsprechenden Arbeitsaufträgen und Dokumentationsfunktionen wird gemeinsam erstellt und aktiv umgesetzt. | Für alle wichtigen Gewerke ist festgelegt, wo und wie die einzelnen Qualitätsaspekte kontrolliert und dokumentiert werden. — printed p.34', verification_note='md-verified 2026-09-05 (§4.7.2 p.34; §5.6.2 p.51 "Der vereinbarte Qualitätssicherungsplan (siehe 4.7.2) wird umgesetzt") [VC]', verified_at=now() where id='f03d9332-c660-42fe-836c-84f88c07a0ce' and verification_status not in ('verified_against_standard','corrected');

-- hoai_grundleistungen_limits
update public.fields set verification_status='verified_against_standard', verification_quote='Dem Auftraggeber muss bewusst sein, dass selbst bei Verwendung aller Grundleistungen der HOAI keine umfassenden Projektmanagementleistungen beauftragt sind. — printed p.19', verification_note='md-verified 2026-09-05 (§4.1 p.19) [VC]', verified_at=now() where id='b7a3e413-0594-4573-9bbb-9a2840ceec48' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-10 Risikomanagement ----------

-- risk_register_present
update public.fields set verification_status='verified_against_standard', verification_quote='Eine sorgfältig erstellte Risikoanalyse ist die Grundlage für ein wirksames Risikomanagement, das in regelmäßigen Zeitabständen oder vor Beginn einer nächsten Projektphase auf den aktuellen Stand gebracht wird. | Fundierte Risikoanalysen (Hinweise gibt Merkblatt DWA-M 820-1:2020 in Anhang A) für die verschiedenen Risikogruppen werden durchgeführt. — printed p.35', verification_note='md-verified 2026-09-05 (§4.8.2 p.35) [VC] — the probability/impact rating method is DWA-M 820-1 Anh. A (NR here); §3 p.18 frames it as "sollte in jedem Projekt zum Standard werden" (STAGED S-6 note on REQ-20)', verified_at=now() where id='2ab0a082-91d7-40c4-972c-46d367f8d16d' and verification_status not in ('verified_against_standard','corrected');

-- risk_distribution_fair
update public.fields set verification_status='verified_against_standard', verification_quote='Der bewussten Verteilung der Risiken und der Verantwortlichkeiten zwischen Auftraggeber und Auftragnehmer kommt hier eine große Bedeutung zu. Die Risikoverteilung darf keinen Einfluss auf das Planungsergebnis haben. | Eine sorgfältig erarbeitete Risikoanalyse, inklusive Betrachtungen zu Arbeitssicherheit und Konformität, und eine faire angemessene Verteilung der Risiken sollte in jedem Projekt zum Standard werden. — printed p.15, p.18', verification_note='md-verified 2026-09-05 (§3 p.15 and p.18) [VC]', verified_at=now() where id='8654b2ed-3635-461c-bdf4-584345cf51a8' and verification_status not in ('verified_against_standard','corrected');

-- risk_register
update public.fields set verification_status='verified_against_standard', verification_quote='Fundierte Risikoanalysen (Hinweise gibt Merkblatt DWA-M 820-1:2020 in Anhang A) für die verschiedenen Risikogruppen werden durchgeführt. | Die Risikoanalyse wird in regelmäßigen Zeitabständen aktualisiert. Nicht eingetretene Risiken werden herausgenommen, die eingetretenen Risiken auf Auskömmlichkeit der geplanten Puffer bewertet. Neu erkennbare Risiken werden in der Zusammenstellung ergänzt. — printed p.35', verification_note='md-verified 2026-09-05 (§4.8.2 p.35) [VC] — the register columns (Risikogruppen, Eintretenswahrscheinlichkeit × Schaden) come from DWA-M 820-1 Anh. A Tab. A.1 (NR in this md)', verified_at=now() where id='b9e33d55-257f-4caa-a2b7-7af75354679e' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-11 Bedarfsplanung (LPH 0) ----------

-- framework_conditions_clarified
update public.fields set verification_status='verified_against_standard', verification_quote='Aufstellung einer umfassenden Bedarfsplanung gemäß Merkblatt DWA-M 820-1:2020, sowohl für das Gesamtkonzept als auch für die zur Umsetzung erforderlichen (Teil-)Projekte. Die Förderfähigkeit von Maßnahmen ist geklärt und die Voraussetzungen sind bekannt. | Bestandsunterlagen sind im Rahmen der Bedarfsplanung auf Vollständigkeit, Herkunft, Qualität und Aktualität detailliert zu prüfen. — printed p.37', verification_note='md-verified 2026-09-05 (§5.2.2 p.37) [VC]', verified_at=now() where id='bf9c6027-becc-4279-bd27-b887eaddadbf' and verification_status not in ('verified_against_standard','corrected');

-- forward_planning_done
update public.fields set verification_status='verified_against_standard', verification_quote='Das frühzeitige Anmelden von auszutauschenden Anlagenteilen in der Investitionsplanung oder Instandhaltungsstrategie durch sorgfältiges Assetmanagement, das betriebsbegleitend erfolgt, ist erforderlich. | Spätestens jedoch 2 bis 3 Jahre vor Ablauf der technischen Nutzungsdauer von Anlagen (meist nach 15 Jahren) wird die Bedarfsplanung gestartet. — printed p.38', verification_note='md-verified 2026-09-05 (§5.2.3 p.38) [VC] — the printed "2 bis 3 Jahre" lead time has no gate (STAGED S-8)', verified_at=now() where id='564ac987-8460-4d71-ab74-c88ee7ab34be' and verification_status not in ('verified_against_standard','corrected');

-- changed_needs_recognised
update public.fields set verification_status='verified_against_standard', verification_quote='Entwicklungen im Einzugsgebiet, die sich in Regionalentwicklungsplänen und Flächennutzungsplänen niederschlagen, wie beispielsweise die Ausweisung von Baugebieten oder beabsichtigte Infrastrukturmaßnahmen werden aktiv verfolgt. — printed p.39', verification_note='md-verified 2026-09-05 (§5.2.4 p.39) [VC]', verified_at=now() where id='775c9fba-616c-4b21-a99b-d97d0eea4ea6' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-12 Planungsorganisation und Entscheidungen ----------

-- meeting_protocols_active
update public.fields set verification_status='verified_against_standard', verification_quote='Die Kommunikation muss regelmäßig, vorbereitet, effektiv und dokumentiert sein. Sie zeichnet sich durch die notwendigen Festlegungen, Entscheidungen und Aktivitäten aus. | Besprechungen werden mindestens mit Tagesordnung, Liste offener Punkte (LOP) und Zeitplanung vorbereitet. Für die Besprechung relevante technische Unterlagen und Entscheidungsvorlagen werden mit ausreichend Vorlauf, mindestens fünf Arbeitstage, im Vorfeld verteilt. — printed p.40', verification_note='md-verified 2026-09-05 (§5.3.1 p.40) [VC] — the printed "mindestens fünf Arbeitstage" has no gate (STAGED S-8)', verified_at=now() where id='36cd184d-e0e0-4e5b-868d-e92422c837e1' and verification_status not in ('verified_against_standard','corrected');

-- decisions_documented
update public.fields set verification_status='verified_against_standard', verification_quote='Entscheidungen müssen, einschließlich der Gründe, transparent und nachvollziehbar dokumentiert sein und dauerhaft Bestand haben. Dies führt zu einem stabilen Planungsprozess. | Eine tabellarische Entscheidungsdokumentation wird geführt. — printed p.40', verification_note='md-verified 2026-09-05 (§5.3.2 p.40; §5.3.1 p.40) [VC]', verified_at=now() where id='f927009c-c6d4-43af-8553-907bebace2b0' and verification_status not in ('verified_against_standard','corrected');

-- planning_duration_realistic
update public.fields set verification_status='verified_against_standard', verification_quote='Es sind realistische Terminpläne aufzustellen, die ausreichende Planungszeiträume beinhalten. Sie orientieren sich an der Komplexität der Maßnahme, beispielsweise an Randbedingungen, Schnittstellen, an der Anzahl der Beteiligten, an Konfliktpunkten, an Linienbauwerken, an punktuellen Maßnahmen. — printed p.41', verification_note='md-verified 2026-09-05 (§5.3.4 p.41) [VC]', verified_at=now() where id='5897b0b8-837c-4d11-a8bf-5ef601419bf4' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-13 Drittbeteiligung und Koordination ----------

-- third_parties_engaged_early
update public.fields set verification_status='verified_against_standard', verification_quote='Der Bedarf an Fachplanungen, Gutachten, Rechtsberatung etc. ist intensiv zu recherchieren und realistisch zu ermitteln. Beteiligte Dritte sind möglichst frühzeitig in das Projekt einzubinden und, falls erforderlich, frühzeitig zu beauftragen. Die Anforderungen der Beteiligten sind aktiv einzufordern und in die Planung zu integrieren. — printed p.42', verification_note='md-verified 2026-09-05 (§5.3.5 p.42) [VC]', verified_at=now() where id='ef02656c-7123-45da-be44-457f6ee095ad' and verification_status not in ('verified_against_standard','corrected');

-- decision_competencies_clear
update public.fields set verification_status='verified_against_standard', verification_quote='Die Projektorganisation muss eindeutige Entscheidungswege und Kompetenzen festlegen. Die vom Auftraggeber für die Projektleitung bestellte Person muss die Kompetenz haben, Entscheidungen zu treffen und intern durchzusetzen, die auch Bestand haben müssen. | Eine klare Projektstruktur wird geschaffen. Es ist festgelegt, wer was entscheiden darf und muss. Dies wird im Projekthandbuch dokumentiert. — printed p.42', verification_note='md-verified 2026-09-05 (§5.3.6 p.42) [VC] — same fact as 820-2-05.decision_competencies_mapped (§4.3.3); the source keeps both sections deliberately ("Eventuell vorhandene Dopplungen sind gewollt", Einleitung p.11) — STAGED S-2 observation', verified_at=now() where id='060f1809-e451-476a-b47c-a6fdada1d62f' and verification_status not in ('verified_against_standard','corrected');

-- lot_strategy_documented
update public.fields set verification_status='verified_against_standard', verification_quote='Die für den Projekterfolg erforderliche Aufteilung von Losen und Gewerken wird nach technischen Erfordernissen intensiv durchdacht und transparent begründet. | Unabhängig von einer losweisen Vergabe muss eine Planung gewerkeübergreifend parallel vorangetrieben werden und einer Projektorganisation unterworfen sein. Ziel ist eine aufeinander abgestimmte Planung aller Fachgewerke. — printed p.43, p.44', verification_note='md-verified 2026-09-05 (§5.3.8 p.43; §5.3.9 p.44) [VC]', verified_at=now() where id='714c43a4-fb4a-4dea-ba13-b72d41b82584' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-14 Planungsrisiken und Öffentlichkeitsarbeit ----------

-- public_relations_strategy
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach Projekt ist die Beteiligung der Öffentlichkeit frühzeitig erfolgt. Es werden auch Möglichkeiten zum aktiven Einbringen von Planungsaspekten durch die Bürgerschaft geschaffen. | Zu einem frühen Zeitpunkt, d. h. bereits dann, wenn sich die inhaltlichen Konturen eines Projekts und der sich ergebenden Baumaßnahme abzeichnen, ist es erforderlich, ein Konzept für eine Öffentlichkeitsbeteiligung zu erarbeiten. — printed p.44, p.53', verification_note='md-verified 2026-09-05 (§5.3.10 p.44; §5.6.5 p.53) [VC] — "Je nach Projekt" / "Je nach Größe des Projekts und Öffentlichkeitsinteresse" (p.44): conditional → STAGED S-4 / S-6 (REQ-33)', verified_at=now() where id='61800f10-a697-45e4-a8fd-f858629959a3' and verification_status not in ('verified_against_standard','corrected');

-- risk_analysis_performed
update public.fields set verification_status='verified_against_standard', verification_quote='Risikorelevante Planungsaspekte müssen erkannt und so früh wie möglich so detailliert bearbeitet werden, dass Planungssicherheit entsteht. | Risikoanalysen (siehe Merkblatt DWA-M 820-1:2020) werden gemeinsam mit den Auftragnehmern durchgeführt und regelmäßig, spätestens zu Beginn der jeweils nächsten Projektphase, fortgeschrieben. — printed p.43, p.45', verification_note='md-verified 2026-09-05 (§5.3.7 p.43; §5.3.11 p.45) [VC]', verified_at=now() where id='180e8d70-e904-4161-8848-6bb1fee5ff14' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-15 Planungsphasen-Zusammenfassung ----------

-- lph_completed
update public.fields set verification_status='verified_against_standard', verification_quote='Teil 2 umfasst die Leistungserbringung aller Projektbeteiligten über alle Phasen hinweg, d. h. von der Bedarfsplanung (LPH 0) bis zur Objektbetreuung (LPH 9), inklusive Inbetriebnahme und Übergabe an den Betrieb. | Nach jeder abgeschlossenen Leistungsphase erfolgt eine Freigabe der Planungsleistungen. — printed p.12, p.33', verification_note='md-verified 2026-09-05 (§1 p.12 — also Vorwort p.3, the enum''s LPH 0 reference; §4.6.2 p.33) [VC] — LPH 1–9 labels are HOAI 2021 §43 (NR here). clause_reference §5.3, §5.4 → §1, §4.6.2 proposed in STAGED S-3', verified_at=now() where id='294b6b7d-1008-4294-8b2f-0f7d89ea110f' and verification_status not in ('verified_against_standard','corrected');

-- planning_milestones_met
update public.fields set verification_status='verified_against_standard', verification_quote='Die Terminpläne für die Entscheidungsebenen werden als Rahmenterminpläne bezeichnet. Sie enthalten hauptsächlich die wesentlichen Meilensteine und sind übersichtlich in der Darstellung. | Die Terminkontrolle stellt in regelmäßigen Zeitabständen den Leistungsstand aller Projektbeteiligten fest und vergleicht diese mit den Anforderungen aus dem Terminplan. Abweichungen vom Soll werden über einen Soll-Ist-Vergleich identifiziert. — printed p.26, p.27', verification_note='md-verified 2026-09-05 (§4.4.1 p.26–27) [VC] — phase roll-up flag; the source defines the Meilenstein/Soll-Ist check, not a per-phase summary tick (STAGED S-4)', verified_at=now() where id='36965025-eca8-460c-97b9-d227a750ceb1' and verification_status not in ('verified_against_standard','corrected');

-- cost_estimation_phase_done
update public.fields set verification_status='verified_against_standard', verification_quote='Die Zeit für eine sorgfältige Kostenermittlung wird, da es sich um den letzten Prozess in der Leistungsphase handelt, für eine sorgfältige Bearbeitung zu knapp. Plausibilitätskontrollen unterbleiben deshalb. | Die in HOAI und DIN 276 verlangte Detaillierungstiefe der Kostenermittlungen reicht für die geforderte Genauigkeit oft nicht aus, sie sollte erhöht werden. — printed p.30', verification_note='md-verified 2026-09-05 (§4.5.3 p.30; §4.5.2 p.30) [VC] — phase roll-up flag; the per-phase Kostenermittlung itself is HOAI/DIN 276 (NR) (STAGED S-4)', verified_at=now() where id='8dfdcc6b-c840-4683-98ea-8c099d334154' and verification_status not in ('verified_against_standard','corrected');

-- permitting_complete
update public.fields set verification_status='verified_against_standard', verification_quote='Neben den wasserrechtlichen Genehmigungstatbeständen sind frühzeitig die erforderlichen Genehmigungen aus anderen Bereichen projektspezifisch zusammenzustellen. | Genehmigungsrelevante Punkte werden im Rahmen der Planung nicht ausreichend identifiziert. Die Genehmigungsfähigkeit der vorgelegten Planungen ist nicht geprüft und nicht mit den Behörden abgestimmt. Eine Freigabe der vorgelegten Planungen kann nicht erfolgen. — printed p.45, p.46', verification_note='md-verified 2026-09-05 (§5.4.1 p.45; §5.4.2 p.46) [VC] — phase roll-up of 820-2-16.permit_inventory_complete (STAGED S-2/S-4)', verified_at=now() where id='789c2922-b2df-4cd9-a851-551ca532053a' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-16 Genehmigungen und Erlaubnisse ----------

-- genehmigungsfaehigkeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anforderungen der Genehmigungsbehörden an die Genehmigungsfähigkeit der Planung werden frühzeitig in Erfahrung gebracht, abgestimmt und in der Planung berücksichtigt. | Erforderliche Nachweise werden in Art und Umfang der Erstellung mit der zuständigen Behörde vereinbart. — printed p.46', verification_note='md-verified 2026-09-05 (§5.4.2 p.46) [VC]', verified_at=now() where id='24909064-bf8f-4e32-81b4-605f77e80f4d' and verification_status not in ('verified_against_standard','corrected');

-- property_rights_secured
update public.fields set verification_status='verified_against_standard', verification_quote='Die Beschaffung und Bereitstellung der Baugrundstücke sowie der Grundstücke für Baustelleneinrichtung oder Bodenlagerung sowie von Leitungsrechten gehören ebenso wie die Bereitstellung von Haushalts- oder Finanzmitteln zu den Voraussetzungen für die Planung. Sie sind spätestens zur Einreichung der Genehmigungsunterlagen geklärt. — printed p.46', verification_note='md-verified 2026-09-05 (§5.4.4 p.46) [VC]', verified_at=now() where id='3394689a-2bf3-4790-abe8-0962b22f27fe' and verification_status not in ('verified_against_standard','corrected');

-- permit_conditions_tracked
update public.fields set verification_status='verified_against_standard', verification_quote='Die von den Behörden erteilten Auflagen werden vollständig und sorgfältig beachtet. | Eine aktive Nachverfolgung der Auflagen findet statt und hilft dabei, die Erledigung der Auflagen zu den erforderlichen Zeitpunkten nachweisen zu können. — printed p.47', verification_note='md-verified 2026-09-05 (§5.4.5 p.47) [VC]', verified_at=now() where id='4fc693c4-0393-4cfb-a50d-c04c52872cfe' and verification_status not in ('verified_against_standard','corrected');

-- permit_inventory_complete
update public.fields set verification_status='verified_against_standard', verification_quote='Neben den wasserrechtlichen Planungsanzeigen und -genehmigungen, die in den Landeswassergesetzen in Verbindung mit dem Wasserhaushaltsgesetz (WHG) geregelt sind, können für den Bau und den Betrieb von Abwasseranlagen weitere Genehmigungen erforderlich werden. Neben Gestattungen und Liegenschaftsvereinbarungen sind hier beispielsweise Baugenehmigungen nach Bauordnungsrecht der einzelnen Länder, Nachweise zum Brandschutz oder zur Arbeitssicherheit oder Konformitätserklärungen und CE-Kennzeichnungen [...] zu nennen. Neben den wasserrechtlichen Genehmigungstatbeständen sind frühzeitig die erforderlichen Genehmigungen aus anderen Bereichen projektspezifisch zusammenzustellen. — printed p.45', verification_note='md-verified 2026-09-05 (§5.4.1 p.45) [VC] — the Rechtsbereich categories (Wasser/Bau/Umwelt/Naturschutz/Sonstige) are EKOWAI''s grouping of the printed examples', verified_at=now() where id='4ea88575-39ad-4200-b17c-c68d30af3925' and verification_status not in ('verified_against_standard','corrected');

-- discharge_permit_extension
update public.fields set verification_status='verified_against_standard', verification_quote='Ein wichtiger Punkt ist die zeitliche Befristung von Erlaubnissen. Also laufen insbesondere die Erlaubnisse für die Einleitungen aus Kläranlagen oder Kanalnetzen regelmäßig wieder ab und müssen rechtzeitig verlängert oder neu beantragt werden. | Mindestens zwei Jahre vor Ablauf der Frist sollte mit der Genehmigungsbehörde (Wasserbehörde) geklärt werden, welche aktuellen Anforderungen an die Einleitung aufgestellt werden und welche Untersuchungen daraus resultieren. — printed p.45, p.46', verification_note='md-verified 2026-09-05 (§5.4.1 p.45; §5.4.3 p.46) [VC] — the applied/granted/pending/not_required states are EKOWAI''s; the printed "mindestens zwei Jahre" lead time has no gate (STAGED S-8)', verified_at=now() where id='bf7ecbe3-d864-4108-afb9-0241309a53f8' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-17 Nebenangebote und Eignungen ----------

-- nebenangebote_conditions
update public.fields set verification_status='verified_against_standard', verification_quote='Auf Nebenangebote sollte nicht generell verzichtet werden. Die Möglichkeit von Nebenangeboten sollte jedoch begrenzt werden. | Bei zugelassenen Nebenangeboten sind, wie es in der VOB/A gefordert ist, Mindestanforderungen an die Leistung zu formulieren. Der Bieter muss die Mindestanforderungen erfüllen und die Gleichwertigkeit nachweisen. — printed p.48', verification_note='md-verified 2026-09-05 (§5.5.1 p.48) [VC] — the obligation is conditional "Bei zugelassenen Nebenangeboten"; REQ-38 fires unconditionally (STAGED S-5/S-6)', verified_at=now() where id='86a6424e-f3eb-4557-8938-4bece41c064f' and verification_status not in ('verified_against_standard','corrected');

