-- ---------- 820-2-18 Leistungsbeschreibung und Terminpläne ----------

-- rahmenterminplan_attached
update public.fields set verification_status='verified_against_standard', verification_quote='Den Vergabeunterlagen für die Bauleistungen ist ein ausreichend detaillierter und alle Aspekte des Projekts berücksichtigender Terminplan beigefügt. [...] Insbesondere ist der Terminplan von realistischen Zeitansätzen ausgegangen und mit den notwendigen Pufferzeiten versehen. | Der ausreichend detaillierte, realistische und mit den notwendigen Pufferzeiten versehene Terminplan des Auftraggebers ist Teil der Vergabeunterlagen für die Leistungen der zu beauftragenden Unternehmen. — printed p.50', verification_note='md-verified 2026-09-05 (§5.5.4 p.50) [VC]', verified_at=now() where id='729931c8-28b4-4d60-9d5a-91444891ae43' and verification_status not in ('verified_against_standard','corrected');

-- leistungsbeschreibung_type
update public.fields set verification_status='verified_against_standard', verification_quote='In den Projekten der Wasserwirtschaft sollten globale funktionale Leistungsbeschreibungen vermieden werden. | Im Bereich Bauwerk ist die Leistungsbeschreibung mit Leistungsverzeichnis die geeignete Vorgehensweise. Für Teilbereiche kann die funktionale Leistungsbeschreibung auch hier ein geeigneter Lösungsansatz sein. | Im Bereich der Maschinen- und Anlagentechnik eignen sich häufiger funktionale Leistungsbeschreibungen mit vorgeschriebenen Qualitäten. — printed p.49', verification_note='md-verified 2026-09-05 (§5.5.3 p.49) [VC] — the source recommends per Bereich (Bauwerk → LV; M-/V-Technik → funktional), it does not require a single project-wide choice; the "Leistungsprogramm" wording in the label is EKOWAI''s', verified_at=now() where id='75860dfb-e7a1-4715-b8fc-960f3ec31be0' and verification_status not in ('verified_against_standard','corrected');

-- testbetrieb_vs_abnahme_choice
update public.fields set verification_status='verified_against_standard', verification_quote='In den Vergabeunterlagen für die ausführenden Firmen muss der Auftraggeber formulieren, ob er sich für den Testbetrieb mit anschließender Abnahme, die Abnahmeprüfungen ohne Testbetrieb oder eine Mischform zwischen beiden entscheidet. | Der Regelfall ist der Testbetrieb mit anschließender Abnahmeprüfung. In Einzelfällen kann es sinnvoll sein, nur die Abnahmeprüfung bei den für den Betrieb nicht direkt relevanten Gewerken, wie beispielsweise Betonbau oder Ausbaugewerke, frühzeitig nach Fertigstellung des jeweiligen Gewerks, durchzuführen. — printed p.55', verification_note='md-verified 2026-09-05 (§5.7.1 p.55) [VC] — printed "muss … formulieren" with no gate on IS NOT NULL (STAGED S-8)', verified_at=now() where id='ba75f43e-b701-4cec-88de-64f1dd9f411e' and verification_status not in ('verified_against_standard','corrected');

