-- vergabeverfahren_used
update public.fields set verification_status='verified_against_standard', verification_quote='In der Phase der Ausführungsplanung bzw. der Vorbereitung der Vergabe ist die Art der Vergabeverfahren für die Bauleistungen im konkreten Projekt zu definieren. — printed p.49', verification_note='md-verified 2026-09-05 (§5.5.3 p.49) [VC] — clause_reference §5.5 → §5.5.3 proposed in STAGED S-3', verified_at=now() where id='19cb9a0a-71e3-4e75-b1ac-88862ceb0fb5' and verification_status not in ('verified_against_standard','corrected');

-- auswahlentscheidung_dokumentiert
update public.fields set verification_status='verified_against_standard', verification_quote='In der Wertungsphase werden Angebote konsequent ausgeschlossen, die diese Anforderungen nicht erfüllen. | In der Wertungsphase ist sehr sorgfältig zu prüfen, ob die mit einem zulässigen Nebenangebot angebotene Lösung für die Realisierung eines Projekts tatsächlich erhebliche Vorteile bringt. | Entscheidungen müssen, einschließlich der Gründe, transparent und nachvollziehbar dokumentiert sein und dauerhaft Bestand haben. — printed p.48, p.40', verification_note='md-verified 2026-09-05 (§5.5.2 p.48; §5.5.1 p.48; §5.3.2 p.40) [VC] — partial: the Vergabevermerk as the award-decision record is a DWA-M 820-1 §8.3 artefact (NR here); this part only carries the general decision-documentation rule (STAGED S-4)', verified_at=now() where id='adce2960-b7c7-448d-bdcd-df9c6aafc196' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-20 Baucontrolling und Qualität ----------

-- quality_supervision_active
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bauüberwachung muss die geschlossenen Verträge, inklusive der Leistungsverzeichnisse, kennen und sicherstellen, dass die in den Vergabeunterlagen bzw. den Bauverträgen formulierten Qualitätsanforderungen auch tatsächlich um- und durchgesetzt werden. — printed p.51', verification_note='md-verified 2026-09-05 (§5.6.2 p.51) [VC]', verified_at=now() where id='ac9d0b5c-a354-4291-9a0c-9ff8289c60c8' and verification_status not in ('verified_against_standard','corrected');

-- bauueberwachung_competencies
update public.fields set verification_status='verified_against_standard', verification_quote='Der Auftraggeber muss eindeutig festlegen, welche Kompetenzen einer externen Bauüberwachung zugebilligt werden sollen. Es müssen Entscheidungswege sowohl auftraggeberintern als auch zwischen Bauüberwachung und Auftraggeber klar formuliert werden. | Der Entscheidungsrahmen (z. B. bis 5 T€ oder weitergehende Vollmacht) ist festzulegen. Anweisungen sind zu dokumentieren, beispielsweise im Projekthandbuch (Anhang B). — printed p.52', verification_note='md-verified 2026-09-05 (§5.6.3 p.52) [VC] — scoped to an EXTERNAL Bauüberwachung ("Wird in einem Projekt die Bauüberwachung durch einen Auftragnehmer wahrgenommen", p.52)', verified_at=now() where id='09fea5c1-f46b-4432-8e80-c052e8164a94' and verification_status not in ('verified_against_standard','corrected');

-- controlling_reports_frequency
update public.fields set verification_status='verified_against_standard', verification_quote='Das Kosten-, Qualitäts- und Termincontrolling ist als Regelaufgabe intensiv und mit Nachdruck durchzuführen und vom Auftraggeber regelmäßig zu kontrollieren. | Als wesentliches Hilfsmittel ist hier eine regelmäßige, zum Beispiel monatliche Kontrolle der auf der Baustelle erbrachten Leistungen, der Übereinstimmung mit den Planunterlagen, der in die Abrechnung gestellten Massen und der laut Leistungsbeschreibung zu erbringenden Massen erforderlich. — printed p.50', verification_note='md-verified 2026-09-05 (§5.6.1 p.50) [VC] — the source prints "zum Beispiel monatlich"; the weekly…ad_hoc enum is EKOWAI''s (enum regulation_reference says §4.3.6 while the field cites §5.6.1 — STAGED S-3)', verified_at=now() where id='2c6f4d23-3605-4db7-94bf-f3013f511d90' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-21 Bauänderungen und Öffentlichkeitsarbeit ----------

-- change_orders
update public.fields set verification_status='verified_against_standard', verification_quote='Werden Änderungen aus besonderen Gründen erforderlich, ist das Änderungsmanagement konsequent zu führen. | Der Auslöser bzw. Verursacher für die Projektänderung und die Kostenübernahmen werden geklärt und müssen in Textform dokumentiert werden. Auswirkungen auf die Projektziele (Termine, Kosten, Qualitäten, inklusive Planungskosten) sind geklärt und beschrieben. Konsequenzen auf den weiteren Projektverlauf sind bekannt. | Das gilt in der Bauphase nicht nur für den Abrechnungsstand, sondern auch für die Projektänderungen, Nachträge und die Kostenprognose. — printed p.53, p.26, p.31', verification_note='md-verified 2026-09-05 (§5.6.4 p.53; §4.3.7 p.26; §4.5.4 p.31; Anhang A item 4.3 "Projektänderungen und Nachträge" p.84) [VC] — clause_reference "§5.6.4, §5.6.5" → "§5.6.4, §4.3.7" proposed in STAGED S-3 (§5.6.5 is Öffentlichkeitsarbeit)', verified_at=now() where id='ca8a829e-7f73-42fc-a3b0-5299c66742b8' and verification_status not in ('verified_against_standard','corrected');

-- oeffentlichkeitsarbeit_durchgefuehrt
update public.fields set verification_status='verified_against_standard', verification_quote='Durch eine angepasste, intensive Öffentlichkeitsarbeit können Beschwerden aus der Bürgerschaft verhindert werden. Information und Aufklärung tragen erheblich zum Erfolg eines Projekts bei. | Proaktive Informationen der Betroffenen und Erklärungen der erforderlichen Maßnahmen führen zu besserer Akzeptanz in der Bevölkerung. — printed p.53', verification_note='md-verified 2026-09-05 (§5.6.5 p.53) [VC] — clause_reference "§5.6.4, §5.6.5" → "§5.6.5" proposed in STAGED S-3', verified_at=now() where id='8fa75c93-3bdf-4b9c-85bf-3dcbc6b33016' and verification_status not in ('verified_against_standard','corrected');

-- kommunikations_plan_dokumentiert
update public.fields set verification_status='verified_against_standard', verification_quote='Zu einem frühen Zeitpunkt, d. h. bereits dann, wenn sich die inhaltlichen Konturen eines Projekts und der sich ergebenden Baumaßnahme abzeichnen, ist es erforderlich, ein Konzept für eine Öffentlichkeitsbeteiligung zu erarbeiten. | Probate Mittel sind Informationsveranstaltungen für die Bürgerschaft, Tage der offenen Tür auf Baustellen, eine Projekt-Homepage etc. Auch die sozialen Medien bieten geeignete Plattformen. — printed p.53', verification_note='md-verified 2026-09-05 (§5.6.5 p.53) [VC] — same artefact as 820-2-03.communication_concept / 820-2-14.public_relations_strategy (STAGED S-2); clause_reference → §5.6.5 (S-3)', verified_at=now() where id='f6015d7a-180f-42cd-b9f5-e6073e5bc967' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-22 Testbetrieb und Abnahme ----------

-- testbetrieb_planned
update public.fields set verification_status='verified_against_standard', verification_quote='Der geplante Testbetrieb ist beschrieben, ausgeschrieben und wird bezahlt. Der Auftraggeber hat die Leistungen des Auftragnehmers sowie der ausführenden Firmen für den Testbetrieb beschrieben. Die Durchführung des Testbetriebs ist Teil der vertraglichen Leistung. | Der Zeitpunkt des Testbetriebs ist vertraglich festgelegt. Er entfaltet seine optimale Wirkung nur dann, wenn er vor der Abnahme stattfindet. — printed p.56', verification_note='md-verified 2026-09-05 (§5.7.2 p.56; Bild 3 p.54) [VC] — conditional on the §5.7.1 choice: "Der Regelfall ist der Testbetrieb … In Einzelfällen kann es sinnvoll sein, nur die Abnahmeprüfung … durchzuführen" (p.55) → REQ-46 guard proposed in STAGED S-5', verified_at=now() where id='c6f211f5-9e5d-4fcb-86e4-2edf6b898e6e' and verification_status not in ('verified_against_standard','corrected');

-- abnahme_per_bild4
update public.fields set verification_status='verified_against_standard', verification_quote='Die Abnahme ist gesetzlich vorgeschrieben, jedoch nicht weiter ausgestaltet. [...] Die hier vorgeschlagene Abnahmeprüfung geht über eine reine Sichtprüfung hinaus, weil sie stichpunktartige Kontrollen der Funktionalität (z. B. Leistungsgrenzen) umfasst. | Statt einer reinen Abnahme findet eine Abnahmeprüfung statt, die sich dadurch auszeichnet, dass über die reine Sichtprüfung hinaus relevante Funktionalitäten geprüft werden. — printed p.57', verification_note='md-verified 2026-09-05 (§5.7.3 p.57; Bild 4 p.55) [VC] — the Abnahmeprüfung procedure is printed as "vorgeschlagen"; only the Abnahme itself is mandatory (STAGED S-6 on REQ-47)', verified_at=now() where id='45ffac24-13a5-47e6-becf-0f91382839ee' and verification_status not in ('verified_against_standard','corrected');

-- testbetrieb_documentation_precondition
update public.fields set verification_status='verified_against_standard', verification_quote='Die Schlussdokumentation muss im Vertrag zur Voraussetzung für die Abnahme gemacht werden. | Die Vorlage der vollständigen Unterlagen muss als Voraussetzung für die Abnahme vereinbart werden. Liegen diese Unterlagen vor, schließt sich daran die Abnahme an. — printed p.56, p.57', verification_note='md-verified 2026-09-05 (§5.7.2 p.56–57) [VC]', verified_at=now() where id='cb0f0e21-7cb3-4860-a50a-bd1f9a46d56c' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-23 Dokumentation und Einweisung ----------

-- operating_manuals_complete
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderlichen Unterlagen der Betriebsanleitung und der technischen Dokumentation liegen zum Zeitpunkt des Montageendes vollständig vor. So ist sichergestellt, dass die Vollständigkeit geprüft werden kann und dass sich das Betriebspersonal mit den Unterlagen vertraut machen kann. | Sprache und Inhalte der technischen Dokumentation müssen dem Projekt angepasst sein und dem jeweiligen Lieferanteil präzise entsprechen. — printed p.58', verification_note='md-verified 2026-09-05 (§5.7.4 p.58) [VC]', verified_at=now() where id='30f5a4dd-6395-4080-8de3-8ad3cd69ae3a' and verification_status not in ('verified_against_standard','corrected');

-- training_complete
update public.fields set verification_status='verified_against_standard', verification_quote='Einweisungen des Betriebspersonals erfolgen in jedem Fall in ausreichender Tiefe, um einen optimalen und sicheren Betrieb neuer Anlagenteile zu ermöglichen. | Mit der Vorbereitung der Inbetriebnahme einer neu errichteten oder umgebauten Anlage ist es notwendig, dass das Betriebspersonal in der Bedienung der Anlage unterwiesen ist. — printed p.59', verification_note='md-verified 2026-09-05 (§5.7.5 p.59) [VC]', verified_at=now() where id='7f572658-4dfa-497a-a29a-e7ee8c8f25fa' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-24 Gewährleistungsmanagement ----------

-- warranty_start_date
update public.fields set verification_status='verified_against_standard', verification_quote='Es gibt einen eindeutigen Abnahmezeitpunkt für jeden Auftragnehmer. | Die Abnahmen werden mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfrist dokumentiert. — printed p.61', verification_note='md-verified 2026-09-05 (§5.8.2 p.61; §5.7.1 p.54 "Mit der Abnahme geht die Gefahr auf den Auftraggeber über, der Werklohn wird fällig, die Gewährleistungsfrist beginnt.") [VC] — unit="date" on a date field is not a unit (STAGED S-3b)', verified_at=now() where id='ff0266af-2af1-412e-9ecd-d4faaca720dd' and verification_status not in ('verified_against_standard','corrected');

-- warranty_end_date
update public.fields set verification_status='verified_against_standard', verification_quote='Das Ende der Gewährleistungszeit wird jeweils durch ein Datum benannt. | Es wird ein Gewährleistungskalender, mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfristen, für jeden Auftragnehmer und für jede ausführende Firma geführt. — printed p.61', verification_note='md-verified 2026-09-05 (§5.8.2 p.61) [VC] — the source asks for a per-contractor Gewährleistungskalender; a single start/end pair is EKOWAI''s simplification. unit="date" (STAGED S-3b)', verified_at=now() where id='4745fdc3-e710-4c8b-9009-8f7ba280bfef' and verification_status not in ('verified_against_standard','corrected');

-- defect_tracking_active
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist festgelegt, wer für die Phase LPH 9 verantwortlich ist. Es ist festzulegen, wie und in welcher Frequenz die Kontrollen erfolgen müssen. Es sind auskömmliche Ressourcen einzusetzen. | Festgestellte Mängel sind zeitnah zum Auftreten bei der ausführenden Firma zu rügen. — printed p.62', verification_note='md-verified 2026-09-05 (§5.8.3 p.62) [VC]', verified_at=now() where id='d053b066-3d7a-4ecf-93cf-737d3c1966c0' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-25 Richtlinienverwaltung ----------

-- guidelines_update_schedule
update public.fields set verification_status='verified_against_standard', verification_quote='Es gibt einen Aktualisierungsprozess, der vorausschauend und sorgfältig, mit genügend Zeit, die Aktualität der Richtlinien und Regelwerke sicherstellt. | Es gibt eine Person mit Funktion im Organigramm, die die Prozessverantwortung übernimmt und mit entsprechenden Kompetenzen ausgestattet ist. — printed p.66', verification_note='md-verified 2026-09-05 (§6.3.3 p.66; §6.3.2 p.65) [VC]', verified_at=now() where id='dcce5499-f611-4fc6-83fd-2abe5ca83422' and verification_status not in ('verified_against_standard','corrected');

-- approval_release_process
update public.fields set verification_status='verified_against_standard', verification_quote='Trotz aller Aktualisierungsbemühungen kann der Fall eintreten, dass es projektbezogene Abweichungen von Richtlinien und Regelwerken gibt. Hier muss ein Prozess eingerichtet sein, der den Umgang mit Abweichungen bis hin zur Entscheidung und Freigabe seitens des Auftraggebers (Bauherr und Betrieb) regelt. | Es gibt gut funktionierende Prozesse zur Aktualisierung von Richtlinien und Regelwerken, sodass eine aktive Unterstützung der Projektnotwendigkeiten erfolgen kann und gegebenenfalls Innovationen möglich sind. — printed p.65, p.66', verification_note='md-verified 2026-09-05 (§6.3.1 p.65; §6.3.3 p.66) [VC]', verified_at=now() where id='9bd0feec-389b-4349-bffc-1de553cc12b6' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-26 Innovationsmanagement ----------

-- innovation_scope_defined
update public.fields set verification_status='verified_against_standard', verification_quote='Die Rahmenbedingungen für Innovationen werden über die zu erreichenden Ergebnisparameter (in einer gewissen Bandbreite) definiert und festgelegt. | Die Ausschreibungsunterlagen werden innovationsoffen aufgebaut. — printed p.67, p.70', verification_note='md-verified 2026-09-05 (§7.2 p.67; §7.3.5 p.70; §7.1 p.67 "Es ist gewünscht, dass in den Planungsprozessen auch Innovationen … stattfinden") [VC]', verified_at=now() where id='e794837a-8b30-44b4-aa7a-c2150f440941' and verification_status not in ('verified_against_standard','corrected');

-- liability_clarified
update public.fields set verification_status='verified_against_standard', verification_quote='Die Haftungsfragen, die sich insbesondere mit neuartigen, innovativen Lösungsansätzen ergeben, die nicht die anerkannten Regeln der Technik erfüllen, sind vertraglich fair verteilt. Die Auftragnehmer hatten die Möglichkeit, die zu übernehmenden Risiken einzupreisen. Sofern das nicht möglich ist, greift ein Mechanismus zur Risikoverteilung im Vertrag. — printed p.72', verification_note='md-verified 2026-09-05 (§7.5 p.72) [VC]', verified_at=now() where id='8477d8a9-d711-4aac-82eb-7321bf109c40' and verification_status not in ('verified_against_standard','corrected');

-- ip_rights_defined
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist dem Auftraggeber nicht erlaubt, Planungen, die er für ein spezifisches Projekt erworben hat, ungefragt und ohne Vergütung für andere Projekte zu verwenden oder an Dritte weiterzugeben. | Im Vertrag mit dem Auftraggeber sollten der Umfang der Nutzung und die Nutzungsbefugnis sowie die dafür zu zahlende Vergütung angemessen und klar geregelt werden. — printed p.72, p.73', verification_note='md-verified 2026-09-05 (§7.6.1 p.72; §7.6.2 p.73; §7.6.3 p.73 "Grundsätzlich sollte er deshalb die Vergütung … in einer eigenen Position regeln") [VC] — the contractual regulation is "sollte" (STAGED S-6 on REQ-56)', verified_at=now() where id='115f6065-2a1d-48ff-b0ec-7bda9fe34ef6' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-27 Digitale Planung und BIM ----------

-- software_products_defined
update public.fields set verification_status='verified_against_standard', verification_quote='Software und Hardware, Modelltechnik und andere sind IT-technische Werkzeuge zur Umsetzung von Planungs- und Projektorganisationsprozessen. Die einzusetzenden Werkzeuge werden vor Projektbeginn zwischen Auftraggeber und Auftragnehmer beraten und festgelegt. | Übergabeformate für die Projektergebnisse werden festgelegt. Es werden keine Software-Produkte vorgeschrieben. — printed p.74', verification_note='md-verified 2026-09-05 (§8.1 p.74; §8.2.1 p.74) [VC] — caveat: the source agrees TOOLS and fixes EXCHANGE FORMATS but explicitly forbids prescribing software products; a required "eingesetzte Software" register inverts §8.2.1 (STAGED S-4)', verified_at=now() where id='373d2b0d-a278-41ef-a77a-de4674e12502' and verification_status not in ('verified_against_standard','corrected');

-- data_quality_checked
update public.fields set verification_status='verified_against_standard', verification_quote='Fünf der zahlreichen Anforderungen an die Qualität der Daten sind hier beispielhaft genannt: Vollständigkeit, Eindeutigkeit, Korrektheit, Aktualität, Genauigkeit. | Die Qualität der vom Auftraggeber bereitgestellten Daten muss vor der Ausschreibung von Planungsleistungen bekannt sein. Nur so kann eine belastbare Grundlage der Projektbearbeitung geschaffen werden. — printed p.12, p.75', verification_note='md-verified 2026-09-05 (§2.1 Datenqualität p.12; §8.2.2 p.75) [VC]', verified_at=now() where id='41f469af-6d61-43bd-a236-6142fb1801d6' and verification_status not in ('verified_against_standard','corrected');

-- bim_basics_established
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist geprüft, ob die BIM-Methode beim Auftraggeber angewendet werden kann, ob das Know-how und die Ressourcen zur Verfügung stehen. | Die Anforderungen des Auftraggebers sind in den AIA (Auftraggeberinformationsanforderungen) eindeutig und umfassend beschrieben. — printed p.77', verification_note='md-verified 2026-09-05 (§8.3.2 p.77) [VC]', verified_at=now() where id='6b6fbee0-e088-4f1b-8b55-cbc1fe4ea025' and verification_status not in ('verified_against_standard','corrected');

-- data_platform_defined
update public.fields set verification_status='verified_against_standard', verification_quote='In Projekten ist es sinnvoll, das Datenmanagement im Projekt auf einer (webbasierten) Plattform zu zentralisieren. Dies führt nur dann zum Erfolg, wenn alle Beteiligten die Plattform diszipliniert nutzen. Eine redundante Datenhaltung oder einen parallelen Datenaustausch außerhalb der Plattform darf es nicht geben. Hierzu ist eine klare Verantwortlichkeit zu benennen (Administrator), der unter Beachtung des Datenschutzes ein Rechtekonzept aufstellt und die Struktur mit Inhalten, Ablagesystem, Freigaben, Datenstruktur etc. festlegt. — printed p.78', verification_note='md-verified 2026-09-05 (§8.3.3 p.78; CDE abbreviation §2.2 p.13) [VC]', verified_at=now() where id='ea43d34c-0c0e-45ba-894b-bac721ff4fdd' and verification_status not in ('verified_against_standard','corrected');

-- ---------- 820-2-28 Datenmanagement und Sicherheit ----------

-- data_security_measures
update public.fields set verification_status='verified_against_standard', verification_quote='Bei allen Lösungen sind Anforderungen aus technischen Standards und Sicherheitsstandards wie den BSI-Grundschutz und die DSGVO zu berücksichtigen. | Unter anderem sollten folgende Aspekte Berücksichtigung finden: | I Einbindung der IT-Verantwortlichen, | I Trennung von Projektbereich und Produktion bzw. Betrieb, | I Bereitstellung ausreichender Bandbreiten, | I strukturierte Zugriffsrechte nach Projektfunktion, | I Lebensdauer, Produktzyklen, Versionierung von Software, Tools und Plattformen, | I technische und organisatorische Maßnahmen (TOM), | I Datenverfügbarkeit (Datenübertragbarkeit, Übertragbarkeit von alter auf neue Projektplattform), | I rechtliche Aspekte von getroffenen Vereinbarungen, | I Dokumentation von Zugriffsrechten (Nachweis der Beendigung der Zugriffsrechte). — printed p.83', verification_note='md-verified 2026-09-05 (§8.8 p.83) [VC] — the BSI/DSGVO obligation is binding; the itemised aspects are "sollten"', verified_at=now() where id='356b631e-9c8d-4cdd-987e-80731f97071f' and verification_status not in ('verified_against_standard','corrected');

-- digital_rights_clarified
update public.fields set verification_status='verified_against_standard', verification_quote='Genauso bedeutsam sind Fragen der Rechte an den digitalen Modellen und Daten, sowie der Urheberund Verwertungsrechte. Geklärt werden muss auch, auf welchen Plattformen (Cloud oder Server) die Daten gehalten werden, wer der Eigentümer der Daten ist, wer die Daten sichert und archiviert. | Das bedeutet, der Auftraggeber darf die Daten für das Projekt verwenden (z. B. ein Schachtmodell), nicht aber für andere Projekte, wenn er sich diese Rechte nicht ausdrücklich und gegen Vergütung hat einräumen lassen. — printed p.16, p.83', verification_note='md-verified 2026-09-05 (§3 p.16; §8.9 p.83) [VC] — md OCR prints "Urheberund" for "Urheber- und"', verified_at=now() where id='645d523f-e73c-4a14-9aae-4d668862723a' and verification_status not in ('verified_against_standard','corrected');

-- gis_data_quality
update public.fields set verification_status='verified_against_standard', verification_quote='Die Qualität von in Geoinformationssystemen verarbeiteten Daten ist in Metadaten dokumentiert. Angaben zu Herkunft, Aktualität und Genauigkeit sind vorhanden. | Bei Verwendung von frei verfügbaren Daten aus Geoinformationssystemen wird auf eine dokumentierte Datenqualität geachtet. — printed p.82', verification_note='md-verified 2026-09-05 (§8.7 p.82) [VC] — the high/medium/low/unknown scale is EKOWAI''s; the source asks for documented Metadaten (Herkunft, Aktualität, Genauigkeit)', verified_at=now() where id='5021a9ad-db0a-4dea-b439-a3a22d8e4764' and verification_status not in ('verified_against_standard','corrected');
